INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss jeder Zoneneintrag eine TTL (Time to Live) enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "TTL definiert Gültigkeit"}, {"text": "Nein", "correct": false, "because": "TTL ist zwingend, kann aber von Zone geerbt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein A-Eintrag sowohl IPv4- als auch IPv6-Adressen enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "A ist nur für IPv4, AAAA für IPv6"}, {"text": "Ja", "correct": false, "because": "Separate Einträge nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein NS-Eintrag erforderlich, um eine Zone funktionsfähig zu machen?', 2, '[{"text": "Ja", "correct": true, "because": "Nameserver definieren Zuständigkeit"}, {"text": "Nein", "correct": false, "because": "NS ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Zoneneinträge dynamisch durch Clients aktualisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Dynamic DNS (DDNS) erlaubt Updates"}, {"text": "Nein", "correct": false, "because": "DDNS ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein MX-Eintrag immer eine IP-Adresse enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "MX verweist auf Hostnamen, nicht direkt IPs"}, {"text": "Ja", "correct": false, "because": "Hostnamen sind üblich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Zoneneintrag definiert die grundlegenden Eigenschaften einer DNS-Zone?', 2, '[{"text": "SOA", "correct": true, "because": "Start of Authority enthält Zone-Details"}, {"text": "NS", "correct": false, "because": "Für Nameserver"}, {"text": "A", "correct": false, "because": "Für IPv4-Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Eintrag wird verwendet, um eine IPv6-Adresse einer Domain zuzuweisen?', 3, '[{"text": "AAAA", "correct": true, "because": "Für IPv6-Adressen"}, {"text": "A", "correct": false, "because": "Für IPv4-Adressen"}, {"text": "CNAME", "correct": false, "because": "Für Aliase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Zoneneintrag erlaubt es, eine Subdomain auf eine andere Domain zu verweisen?', 2, '[{"text": "CNAME", "correct": true, "because": "Canonical Name für Aliase"}, {"text": "MX", "correct": false, "because": "Für Mailserver"}, {"text": "PTR", "correct": false, "because": "Für Reverse-DNS"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Priorität hat ein MX-Eintrag mit dem Wert 10 im Vergleich zu einem mit 20?', 2, '[{"text": "Höhere Priorität", "correct": true, "because": "Niedrigerer Wert = höhere Priorität"}, {"text": "Niedrigere Priorität", "correct": false, "because": "Falsche Reihenfolge"}, {"text": "Gleiche Priorität", "correct": false, "because": "Werte unterscheiden sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Eintrag wird für die Authentifizierung von E-Mails über SPF verwendet?', 2, '[{"text": "TXT", "correct": true, "because": "TXT enthält SPF-Daten"}, {"text": "MX", "correct": false, "because": "Für Mailserver"}, {"text": "NS", "correct": false, "because": "Für Nameserver"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Zoneneinträge sind für eine funktionale DNS-Zone unerlässlich?', 4, '[{"text": "SOA", "correct": true, "because": "Definiert Zone"}, {"text": "NS", "correct": true, "because": "Nameserver festlegen"}, {"text": "A", "correct": false, "because": "Optional für Hosts"}, {"text": "AAAA", "correct": false, "because": "Optional für IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einträge können in einer Zone für ein Unternehmensnetzwerk sinnvoll sein?', 3, '[{"text": "A (IPv4-Adresse)", "correct": true, "because": "Für Server"}, {"text": "MX (Mailserver)", "correct": true, "because": "Für E-Mail"}, {"text": "TXT (SPF/DKIM)", "correct": true, "because": "Für E-Mail-Sicherheit"}, {"text": "VLAN", "correct": false, "because": "Netzwerkkonfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein SOA-Eintrag?', 4, '[{"text": "Primärer Nameserver", "correct": true, "because": "Definiert Zuständigkeit"}, {"text": "Serial Number", "correct": true, "because": "Für Versionskontrolle"}, {"text": "Refresh-Zeit", "correct": true, "because": "Aktualisierungsintervall"}, {"text": "IP-Adresse", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zoneneinträge unterstützen die Sicherheit einer Domain?', 3, '[{"text": "TXT (DNSSEC)", "correct": true, "because": "Für Signaturen"}, {"text": "TXT (SPF)", "correct": true, "because": "Für E-Mail-Authentifizierung"}, {"text": "MX", "correct": false, "because": "Für Mailserver, nicht Sicherheit"}, {"text": "CAA", "correct": true, "because": "Für Zertifikatsaussteller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fehler können bei Zoneneinträgen auftreten?', 3, '[{"text": "Falsche IP-Adresse", "correct": true, "because": "Führt zu fehlerhafter Auflösung"}, {"text": "Ungültige TTL", "correct": true, "because": "Kann Caching stören"}, {"text": "Fehlender SOA-Eintrag", "correct": true, "because": "Zone ungültig"}, {"text": "Falsche Kanalbreite", "correct": false, "because": "WLAN-spezifisch"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein SOA-Eintrag enthält die Serial Number einer Zone. b) Ein AAAA-Eintrag ist für IPv4-Adressen gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SOA ja, AAAA für IPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein CNAME-Eintrag kann auf eine andere Domain verweisen. b) Ein MX-Eintrag muss eine direkte IP-Adresse enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CNAME ja, MX Hostnamen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein NS-Eintrag definiert den Nameserver einer Zone. b) Ein PTR-Eintrag wird für Forward-DNS verwendet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NS ja, PTR für Reverse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein TXT-Eintrag kann SPF-Daten enthalten. b) Ein A-Eintrag ist für Reverse-Namensauflösung zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TXT ja, A für Forward"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein MX-Eintrag mit Priorität 10 wird vor einem mit 20 bevorzugt. b) Zoneneinträge können dynamisch aktualisiert werden.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Priorität ja, DDNS möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');